namespace Harborline.Kernel.WorkItems;

/// <summary>Structured refusal returned before a multi-command request can reach an executor.</summary>
public sealed record CommandBatchRefusal(string Code, int StatusCode, int CommandCount);

/// <summary>Admission result for one request-scoped command execution.</summary>
public sealed record CommandRequestResult<TResult>(
    bool IsAdmitted,
    IReadOnlyList<TResult> Results,
    CommandBatchRefusal? Refusal);

/// <summary>Enforces one command per request before dispatching any command.</summary>
public static class CommandRequestBoundary
{
    /// <summary>Refuses requests carrying more than one command without invoking the executor.</summary>
    public static async ValueTask<CommandRequestResult<TResult>> ExecuteAsync<TCommand, TResult>(
        IEnumerable<TCommand> commands,
        Func<TCommand, ValueTask<TResult>> executor)
    {
        ArgumentNullException.ThrowIfNull(commands);
        ArgumentNullException.ThrowIfNull(executor);

        var materialized = commands as IReadOnlyList<TCommand> ?? commands.ToArray();
        if (materialized.Count > 1)
        {
            return new(
                false,
                Array.Empty<TResult>(),
                new CommandBatchRefusal("kernel.multi-command-batch", 400, materialized.Count));
        }

        if (materialized.Count == 0)
            return new(true, Array.Empty<TResult>(), null);

        var result = await executor(materialized[0]).ConfigureAwait(false);
        return new(true, new[] { result }, null);
    }
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace Harborline.Kernel.WorkItems.DependencyInjection;

/// <summary>Host environment for work-item composition decisions.</summary>
public enum WorkItemHostEnvironment
{
    /// <summary>Local development; volatile adapters are permitted.</summary>
    Development,

    /// <summary>Automated test host; volatile adapters are permitted.</summary>
    Test,

    /// <summary>Production; volatile adapters are refused.</summary>
    Production,
}

/// <summary>Composition entry points for the work-item kernel's persistence adapters.</summary>
public static class WorkItemServiceCollectionExtensions
{
    /// <summary>
    /// Registers the volatile in-memory work-item store. The adapter keeps every work item, receipt,
    /// audit row and outbox row in process memory only, so composing it in Production would silently
    /// discard tenant state on restart; this registration therefore fails closed there.
    /// </summary>
    public static IServiceCollection AddHarborlineWorkItemsInMemoryStore(
        this IServiceCollection services,
        WorkItemHostEnvironment environment)
    {
        ArgumentNullException.ThrowIfNull(services);
        if (environment == WorkItemHostEnvironment.Production)
            throw new InvalidOperationException("The in-memory work-item store is not permitted in Production.");
        services.TryAddSingleton<InMemoryWorkItemStore>();
        services.TryAddSingleton<IWorkItemStore>(provider => provider.GetRequiredService<InMemoryWorkItemStore>());
        services.TryAddSingleton<IWorkItemJournalReader>(provider => provider.GetRequiredService<InMemoryWorkItemStore>());
        return services;
    }

    /// <summary>
    /// Registers the durable single-process journal store. This adapter is Production-composable; it
    /// uses an in-memory index internally, which is unrelated to the volatile adapter above.
    /// </summary>
    public static IServiceCollection AddHarborlineWorkItemsFileJournalStore(
        this IServiceCollection services,
        string journalPath)
    {
        ArgumentNullException.ThrowIfNull(services);
        ArgumentException.ThrowIfNullOrWhiteSpace(journalPath);
        services.TryAddSingleton<FileJournalWorkItemStore>(_ => new FileJournalWorkItemStore(journalPath));
        services.TryAddSingleton<IWorkItemStore>(provider => provider.GetRequiredService<FileJournalWorkItemStore>());
        services.TryAddSingleton<IWorkItemJournalReader>(provider => provider.GetRequiredService<FileJournalWorkItemStore>());
        return services;
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace Harborline.Kernel.WorkItems;

/// <summary>
/// Single-process checksummed append-only journal adapter. Every committed frame contains the complete
/// materialized kernel state, making recovery deterministic while this local-shadow format remains small.
/// </summary>
public sealed class FileJournalWorkItemStore : IWorkItemStore, IWorkItemJournalReader, IDisposable, IAsyncDisposable
{
    private const string Magic = "HLWI1";
    private const int MaximumFrameBytes = 16 * 1024 * 1024;
    private readonly FileStream _stream;
    private readonly SemaphoreSlim _commitGate = new(1, 1);
    private readonly InMemoryWorkItemStore _inner = new();
    private bool _disposed;

    /// <summary>Opens and recovers one exclusive journal file.</summary>
    public FileJournalWorkItemStore(string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);
        var fullPath = Path.GetFullPath(path);
        Directory.CreateDirectory(Path.GetDirectoryName(fullPath)!);
        _stream = new FileStream(fullPath, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.Read, 4096, FileOptions.Asynchronous);
        try
        {
            Recover();
        }
        catch
        {
            _stream.Dispose();
            throw;
        }
    }

    /// <inheritdoc />
    public Task<WorkItemSnapshot?> GetAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default) =>
        _inner.GetAsync(tenantId, workItemId, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemSnapshot>> ListOpenAsync(string tenantId, CancellationToken cancellationToken = default) =>
        _inner.ListOpenAsync(tenantId, cancellationToken);

    /// <inheritdoc />
    public Task<WorkItemIdempotencyReceipt?> GetReceiptAsync(string tenantId, string idempotencyKey, CancellationToken cancellationToken = default) =>
        _inner.GetReceiptAsync(tenantId, idempotencyKey, cancellationToken);

    /// <inheritdoc />
    public Task<WorkItemStoreResult> CommitCreateAsync(WorkItemCommit commit, CancellationToken cancellationToken = default) =>
        CommitAsync(commit, create: true, cancellationToken);

    /// <inheritdoc />
    public Task<WorkItemStoreResult> CommitTransitionAsync(WorkItemCommit commit, CancellationToken cancellationToken = default) =>
        CommitAsync(commit, create: false, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemEvent>> ReadEventsAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default) =>
        _inner.ReadEventsAsync(tenantId, workItemId, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemAudit>> ReadAuditAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default) =>
        _inner.ReadAuditAsync(tenantId, workItemId, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemOutboxMessage>> ReadOutboxAsync(string tenantId, CancellationToken cancellationToken = default) =>
        _inner.ReadOutboxAsync(tenantId, cancellationToken);

    /// <inheritdoc />
    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        _stream.Dispose();
        _commitGate.Dispose();
    }

    /// <inheritdoc />
    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;
        _disposed = true;
        await _stream.DisposeAsync().ConfigureAwait(false);
        _commitGate.Dispose();
    }

    private async Task<WorkItemStoreResult> CommitAsync(WorkItemCommit commit, bool create, CancellationToken cancellationToken)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        await _commitGate.WaitAsync(cancellationToken).ConfigureAwait(false);
        try
        {
            var candidate = new InMemoryWorkItemStore();
            candidate.ImportState(_inner.ExportState());
            var result = create
                ? await candidate.CommitCreateAsync(commit, cancellationToken).ConfigureAwait(false)
                : await candidate.CommitTransitionAsync(commit, cancellationToken).ConfigureAwait(false);
            if (result.Disposition != WorkItemMutationDisposition.Committed) return result;

            var payload = JsonSerializer.SerializeToUtf8Bytes(candidate.ExportState());
            if (payload.Length > MaximumFrameBytes) throw new InvalidOperationException("Work-item journal frame exceeds the configured resource bound.");
            await AppendFrameAsync(payload, cancellationToken).ConfigureAwait(false);
            _inner.ImportState(candidate.ExportState());
            return result;
        }
        finally
        {
            _commitGate.Release();
        }
    }

    private async Task AppendFrameAsync(byte[] payload, CancellationToken cancellationToken)
    {
        var frameStart = _stream.Length;
        _stream.Position = frameStart;
        var checksum = Convert.ToHexStringLower(SHA256.HashData(payload));
        var header = Encoding.ASCII.GetBytes($"{Magic} {payload.Length} {checksum}\n");
        try
        {
            await _stream.WriteAsync(header, cancellationToken).ConfigureAwait(false);
            await _stream.WriteAsync(payload, cancellationToken).ConfigureAwait(false);
            await _stream.WriteAsync("\n"u8.ToArray(), cancellationToken).ConfigureAwait(false);
            await _stream.FlushAsync(cancellationToken).ConfigureAwait(false);
            _stream.Flush(flushToDisk: true);
        }
        catch
        {
            _stream.SetLength(frameStart);
            _stream.Flush(flushToDisk: true);
            throw;
        }
    }

    private void Recover()
    {
        _stream.Position = 0;
        WorkItemJournalState? latest = null;
        while (_stream.Position < _stream.Length)
        {
            var frameStart = _stream.Position;
            var header = ReadLine();
            if (header is null)
            {
                TruncateIncomplete(frameStart);
                break;
            }

            var fields = header.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            if (fields.Length != 3 || fields[0] != Magic || !int.TryParse(fields[1], out var length) || length < 0 || length > MaximumFrameBytes)
                throw new InvalidDataException("Unknown or malformed work-item journal frame header.");
            if (_stream.Length - _stream.Position < length + 1L)
            {
                TruncateIncomplete(frameStart);
                break;
            }

            var payload = new byte[length];
            _stream.ReadExactly(payload);
            if (_stream.ReadByte() != (byte)'\n') throw new InvalidDataException("Work-item journal frame terminator is corrupt.");
            var checksum = Convert.ToHexStringLower(SHA256.HashData(payload));
            if (!StringComparer.Ordinal.Equals(checksum, fields[2])) throw new InvalidDataException("Work-item journal frame checksum is corrupt.");
            latest = JsonSerializer.Deserialize<WorkItemJournalState>(payload)
                ?? throw new InvalidDataException("Work-item journal frame payload is empty.");
        }

        if (latest is not null) _inner.ImportState(latest);
        _stream.Position = _stream.Length;
    }

    private string? ReadLine()
    {
        var bytes = new List<byte>();
        while (_stream.Position < _stream.Length)
        {
            var value = _stream.ReadByte();
            if (value == (byte)'\n') return Encoding.ASCII.GetString([.. bytes]);
            bytes.Add((byte)value);
            if (bytes.Count > 256) throw new InvalidDataException("Work-item journal header exceeds its resource bound.");
        }
        return null;
    }

    private void TruncateIncomplete(long frameStart)
    {
        _stream.SetLength(frameStart);
        _stream.Flush(flushToDisk: true);
    }
}

namespace Harborline.Kernel.WorkItems;

/// <summary>Thread-safe atomic adapter for tests and development composition.</summary>
public sealed class InMemoryWorkItemStore : IWorkItemStore, IWorkItemJournalReader
{
    private readonly object _gate = new();
    private readonly Dictionary<string, WorkItemSnapshot> _items = new(StringComparer.Ordinal);
    private readonly Dictionary<string, WorkItemIdempotencyReceipt> _receipts = new(StringComparer.Ordinal);
    private readonly List<TenantEvent> _events = [];
    private readonly List<TenantAudit> _audit = [];
    private readonly List<TenantOutbox> _outbox = [];

    /// <inheritdoc />
    public Task<WorkItemSnapshot?> GetAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate) return Task.FromResult(_items.GetValueOrDefault(ItemKey(tenantId, workItemId)));
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemSnapshot>> ListOpenAsync(string tenantId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<WorkItemSnapshot> result = _items
                .Where(row => TenantFromKey(row.Key) == tenantId && row.Value.Status is WorkItemStatus.Running or WorkItemStatus.Parked)
                .Select(row => row.Value)
                .OrderByDescending(row => row.UpdatedAt)
                .ThenBy(row => row.Id, StringComparer.Ordinal)
                .ToArray();
            return Task.FromResult(result);
        }
    }

    /// <inheritdoc />
    public Task<WorkItemIdempotencyReceipt?> GetReceiptAsync(string tenantId, string idempotencyKey, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate) return Task.FromResult(_receipts.GetValueOrDefault(ReceiptKey(tenantId, idempotencyKey)));
    }

    /// <inheritdoc />
    public Task<WorkItemStoreResult> CommitCreateAsync(WorkItemCommit commit, CancellationToken cancellationToken = default) =>
        CommitAsync(commit, create: true, cancellationToken);

    /// <inheritdoc />
    public Task<WorkItemStoreResult> CommitTransitionAsync(WorkItemCommit commit, CancellationToken cancellationToken = default) =>
        CommitAsync(commit, create: false, cancellationToken);

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemEvent>> ReadEventsAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<WorkItemEvent> result = _events.Where(row => row.TenantId == tenantId && row.Value.WorkItemId == workItemId)
                .Select(row => row.Value).OrderBy(row => row.Sequence).ToArray();
            return Task.FromResult(result);
        }
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemAudit>> ReadAuditAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<WorkItemAudit> result = _audit.Where(row => row.TenantId == tenantId && row.Value.WorkItemId == workItemId)
                .Select(row => row.Value).OrderBy(row => row.WorkItemVersion).ToArray();
            return Task.FromResult(result);
        }
    }

    /// <inheritdoc />
    public Task<IReadOnlyList<WorkItemOutboxMessage>> ReadOutboxAsync(string tenantId, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            IReadOnlyList<WorkItemOutboxMessage> result = _outbox.Where(row => row.TenantId == tenantId).Select(row => row.Value).ToArray();
            return Task.FromResult(result);
        }
    }

    internal WorkItemJournalState ExportState()
    {
        lock (_gate)
        {
            return new WorkItemJournalState
            {
                Items = _items.Select(row => new TenantSnapshot(TenantFromKey(row.Key), row.Value)).ToList(),
                Receipts = _receipts.Select(row => new TenantReceipt(TenantFromKey(row.Key), row.Value)).ToList(),
                Events = [.. _events],
                Audit = [.. _audit],
                Outbox = [.. _outbox],
            };
        }
    }

    internal void ImportState(WorkItemJournalState state)
    {
        ArgumentNullException.ThrowIfNull(state);
        lock (_gate)
        {
            _items.Clear();
            foreach (var row in state.Items) _items.Add(ItemKey(row.TenantId, row.Value.Id), row.Value);
            _receipts.Clear();
            foreach (var row in state.Receipts) _receipts.Add(ReceiptKey(row.TenantId, row.Value.Key), row.Value);
            _events.Clear(); _events.AddRange(state.Events);
            _audit.Clear(); _audit.AddRange(state.Audit);
            _outbox.Clear(); _outbox.AddRange(state.Outbox);
        }
    }

    private Task<WorkItemStoreResult> CommitAsync(WorkItemCommit commit, bool create, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(commit);
        cancellationToken.ThrowIfCancellationRequested();
        lock (_gate)
        {
            var receiptKey = ReceiptKey(commit.TenantId, commit.IdempotencyKey);
            if (_receipts.TryGetValue(receiptKey, out var prior))
            {
                return Task.FromResult(new WorkItemStoreResult(
                    prior.Fingerprint == commit.Fingerprint ? WorkItemMutationDisposition.Replayed : WorkItemMutationDisposition.IdempotencyConflict,
                    prior.Fingerprint == commit.Fingerprint ? prior : null));
            }

            var itemKey = ItemKey(commit.TenantId, commit.Snapshot.Id);
            _items.TryGetValue(itemKey, out var current);
            if (create)
            {
                if (current is not null) return Task.FromResult(new WorkItemStoreResult(WorkItemMutationDisposition.VersionConflict, null));
            }
            else if (current is null)
            {
                return Task.FromResult(new WorkItemStoreResult(WorkItemMutationDisposition.NotFound, null));
            }
            else if (current.Version != commit.ExpectedVersion || !StringComparer.Ordinal.Equals(current.CurrentStep, commit.ExpectedStep))
            {
                return Task.FromResult(new WorkItemStoreResult(WorkItemMutationDisposition.VersionConflict, null));
            }

            var receipt = new WorkItemIdempotencyReceipt(commit.IdempotencyKey, commit.Fingerprint, commit.Snapshot, commit.ResultJson);
            _items[itemKey] = commit.Snapshot;
            _receipts.Add(receiptKey, receipt);
            _events.Add(new TenantEvent(commit.TenantId, commit.Event));
            _audit.Add(new TenantAudit(commit.TenantId, new WorkItemAudit(
                commit.Snapshot.Id, commit.Snapshot.Version, commit.ActorId, commit.Event.Action, commit.Event.OccurredAt)));
            foreach (var message in commit.Outbox) _outbox.Add(new TenantOutbox(commit.TenantId, message));
            return Task.FromResult(new WorkItemStoreResult(WorkItemMutationDisposition.Committed, receipt));
        }
    }

    private const char Separator = '\u001f';
    private static string ItemKey(string tenantId, string id) => $"{tenantId}{Separator}{id}";
    private static string ReceiptKey(string tenantId, string id) => $"{tenantId}{Separator}{id}";
    private static string TenantFromKey(string key) => key[..key.IndexOf(Separator, StringComparison.Ordinal)];
}

internal sealed record TenantSnapshot(string TenantId, WorkItemSnapshot Value);
internal sealed record TenantReceipt(string TenantId, WorkItemIdempotencyReceipt Value);
internal sealed record TenantEvent(string TenantId, WorkItemEvent Value);
internal sealed record TenantAudit(string TenantId, WorkItemAudit Value);
internal sealed record TenantOutbox(string TenantId, WorkItemOutboxMessage Value);

internal sealed class WorkItemJournalState
{
    public List<TenantSnapshot> Items { get; init; } = [];
    public List<TenantReceipt> Receipts { get; init; } = [];
    public List<TenantEvent> Events { get; init; } = [];
    public List<TenantAudit> Audit { get; init; } = [];
    public List<TenantOutbox> Outbox { get; init; } = [];
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;

namespace Harborline.Kernel.WorkItems;

internal static class WorkItemCanonical
{
    public static string CreateFingerprint(string tenantId, CreateWorkItemRequest request) => Hash(new
    {
        operation = "create",
        tenantId,
        request.Id,
        request.SubjectRef,
        request.DefinitionKey,
        request.DefinitionVersion,
        request.InitialStep,
        status = (int)request.InitialStatus,
        state = NormalizeJson(request.StateJson),
        basis = NormalizeJson(request.BasisJson),
        outcomes = request.AllowedOutcomes
            .OrderBy(outcome => outcome.FromStep, StringComparer.Ordinal)
            .ThenBy(outcome => outcome.Id, StringComparer.Ordinal)
            .Select(outcome => new
            {
                outcome.Id,
                outcome.FromStep,
                outcome.NextStep,
                status = (int)outcome.NextStatus,
                outcome.IsLoopBack,
            }).ToArray(),
    });

    public static string TransitionFingerprint(string tenantId, TransitionWorkItemRequest request) => Hash(new
    {
        operation = "transition",
        tenantId,
        request.Id,
        request.ExpectedVersion,
        request.OutcomeId,
        result = NormalizeJson(request.ResultJson),
    });

    public static string StepKey(string tenantId, WorkItemSnapshot snapshot) => $"wi1:{Hash(new
    {
        tenantId,
        workItemId = snapshot.Id,
        snapshot.Iteration,
        step = snapshot.CurrentStep,
    })}";

    public static string NormalizeJson(string value)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value);
        using var document = JsonDocument.Parse(value);
        using var buffer = new MemoryStream();
        using (var writer = new Utf8JsonWriter(buffer)) WriteCanonical(writer, document.RootElement);
        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    private static string Hash(object value)
    {
        var bytes = JsonSerializer.SerializeToUtf8Bytes(value);
        return Convert.ToHexStringLower(SHA256.HashData(bytes));
    }

    private static void WriteCanonical(Utf8JsonWriter writer, JsonElement value)
    {
        switch (value.ValueKind)
        {
            case JsonValueKind.Object:
                writer.WriteStartObject();
                foreach (var property in value.EnumerateObject().OrderBy(property => property.Name, StringComparer.Ordinal))
                {
                    writer.WritePropertyName(property.Name);
                    WriteCanonical(writer, property.Value);
                }
                writer.WriteEndObject();
                break;
            case JsonValueKind.Array:
                writer.WriteStartArray();
                foreach (var item in value.EnumerateArray()) WriteCanonical(writer, item);
                writer.WriteEndArray();
                break;
            case JsonValueKind.String:
                writer.WriteStringValue(value.GetString());
                break;
            case JsonValueKind.Number:
                writer.WriteRawValue(value.GetRawText());
                break;
            case JsonValueKind.True:
                writer.WriteBooleanValue(true);
                break;
            case JsonValueKind.False:
                writer.WriteBooleanValue(false);
                break;
            case JsonValueKind.Null:
                writer.WriteNullValue();
                break;
            default:
                throw new JsonException("Unsupported JSON token in work-item content.");
        }
    }
}

namespace Harborline.Kernel.WorkItems;

/// <summary>Lifecycle of one durable process-backed work item.</summary>
public enum WorkItemStatus
{
    /// <summary>An automated continuation may run.</summary>
    Running = 0,
    /// <summary>The process is parked awaiting a typed external or human result.</summary>
    Parked = 1,
    /// <summary>The process completed successfully.</summary>
    Completed = 2,
    /// <summary>The process terminated unsuccessfully.</summary>
    Failed = 3,
}

/// <summary>Immutable caller projection of current work-item state.</summary>
public sealed record WorkItemSnapshot(
    string Id,
    string SubjectRef,
    string DefinitionKey,
    string DefinitionVersion,
    string CurrentStep,
    int Iteration,
    long Version,
    WorkItemStatus Status,
    string StateJson,
    string BasisJson,
    IReadOnlyList<WorkItemOutcome> AllowedOutcomes,
    DateTimeOffset CreatedAt,
    DateTimeOffset UpdatedAt);

/// <summary>A typed lifecycle edge admitted when the item is created.</summary>
public sealed record WorkItemOutcome(
    string Id,
    string FromStep,
    string NextStep,
    WorkItemStatus NextStatus,
    bool IsLoopBack = false);

/// <summary>Creates one process-backed work item in the current tenant.</summary>
public sealed record CreateWorkItemRequest
{
    /// <summary>Stable caller-selected identifier.</summary>
    public required string Id { get; init; }
    /// <summary>Opaque domain subject, such as an inspection submission reference.</summary>
    public required string SubjectRef { get; init; }
    /// <summary>Workflow or process definition key.</summary>
    public required string DefinitionKey { get; init; }
    /// <summary>Definition version pinned for replay.</summary>
    public required string DefinitionVersion { get; init; }
    /// <summary>Initial position.</summary>
    public required string InitialStep { get; init; }
    /// <summary>Initial lifecycle.</summary>
    public WorkItemStatus InitialStatus { get; init; } = WorkItemStatus.Parked;
    /// <summary>Opaque JSON process state.</summary>
    public string StateJson { get; init; } = "{}";
    /// <summary>Opaque JSON decision basis shown before action.</summary>
    public string BasisJson { get; init; } = "{}";
    /// <summary>Closed typed transitions; the kernel, not the caller, derives the next lifecycle.</summary>
    public required IReadOnlyList<WorkItemOutcome> AllowedOutcomes { get; init; }
    /// <summary>Caller-stable retry key.</summary>
    public required string IdempotencyKey { get; init; }
}

/// <summary>Moves one work item from its expected current version and step.</summary>
public sealed record TransitionWorkItemRequest
{
    /// <summary>Target work item.</summary>
    public required string Id { get; init; }
    /// <summary>Optimistic concurrency token read from the snapshot.</summary>
    public required long ExpectedVersion { get; init; }
    /// <summary>Caller-stable retry key.</summary>
    public required string IdempotencyKey { get; init; }
    /// <summary>One allowed outcome ID for the current step.</summary>
    public required string OutcomeId { get; init; }
    /// <summary>Opaque typed result recorded for replay.</summary>
    public string ResultJson { get; init; } = "{}";
}

/// <summary>One immutable transactional-outbox message.</summary>
public sealed record WorkItemOutboxMessage(string MessageId, string Kind, string PayloadJson);

/// <summary>Stable mutation disposition.</summary>
public enum WorkItemMutationDisposition
{
    /// <summary>A new mutation committed.</summary>
    Committed,
    /// <summary>The exact request was already committed and its receipt was replayed.</summary>
    Replayed,
    /// <summary>The retry key was previously used for different content.</summary>
    IdempotencyConflict,
    /// <summary>The expected version or step is stale.</summary>
    VersionConflict,
    /// <summary>No current-tenant item exists.</summary>
    NotFound,
    /// <summary>The requested lifecycle move is invalid.</summary>
    InvalidTransition,
    /// <summary>No active authenticated tenant scope is available.</summary>
    Denied,
}

/// <summary>Mutation result and original replayable receipt.</summary>
public sealed record WorkItemMutationResult(
    WorkItemMutationDisposition Disposition,
    WorkItemSnapshot? Snapshot,
    string? ResultJson)
{
    /// <summary>True when the requested mutation is committed, including exact replay.</summary>
    public bool IsSuccess => Disposition is WorkItemMutationDisposition.Committed or WorkItemMutationDisposition.Replayed;
}

/// <summary>Tenant-scoped deep module for durable work-item behavior.</summary>
public interface IWorkItemKernel
{
    /// <summary>Creates one item, or replays the original receipt.</summary>
    Task<WorkItemMutationResult> CreateAsync(CreateWorkItemRequest request, CancellationToken cancellationToken = default);
    /// <summary>Gets one current-tenant item; foreign and absent IDs both return null.</summary>
    Task<WorkItemSnapshot?> GetAsync(string workItemId, CancellationToken cancellationToken = default);
