using Harborline.Foundation.Authorization;
using Harborline.Foundation.MultiTenancy;
using System.Text.Json;
using System.Text;
using Harborline.Kernel.Core;

namespace Harborline.Kernel.WorkItems;

/// <summary>Default work-item deep-module implementation.</summary>
public sealed class WorkItemKernel : IWorkItemKernel
{
    private readonly ITenantContext _tenantContext;
    private readonly IPartyContext _partyContext;
    private readonly IWorkItemStore _store;
    private readonly TimeProvider _time;

    /// <summary>Constructs the kernel over one scoped actor context and atomic store.</summary>
    public WorkItemKernel(ITenantContext tenantContext, IPartyContext partyContext, IWorkItemStore store, TimeProvider timeProvider)
    {
        _tenantContext = tenantContext ?? throw new ArgumentNullException(nameof(tenantContext));
        _partyContext = partyContext ?? throw new ArgumentNullException(nameof(partyContext));
        _store = store ?? throw new ArgumentNullException(nameof(store));
        _time = timeProvider ?? throw new ArgumentNullException(nameof(timeProvider));
    }

    /// <inheritdoc />
    public async Task<WorkItemMutationResult> CreateAsync(CreateWorkItemRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        ValidateCreate(request);
        var scope = await ScopeAsync(cancellationToken).ConfigureAwait(false);
        if (scope is null) return Denied();

        string fingerprint;
        try { fingerprint = WorkItemCanonical.CreateFingerprint(scope.Value.TenantId, request); }
        catch (JsonException) { return Invalid(); }

        var replay = await ReplayAsync(scope.Value.TenantId, request.IdempotencyKey, fingerprint, cancellationToken).ConfigureAwait(false);
        if (replay is not null) return replay;

        var now = _time.GetUtcNow();
        var outcomes = request.AllowedOutcomes.ToArray();
        var snapshot = new WorkItemSnapshot(
            request.Id, request.SubjectRef, request.DefinitionKey, request.DefinitionVersion, request.InitialStep, 0, 1,
            request.InitialStatus, WorkItemCanonical.NormalizeJson(request.StateJson),
            WorkItemCanonical.NormalizeJson(request.BasisJson), outcomes, now, now);
        var resultJson = "{\"created\":true}";
        var commit = new WorkItemCommit
        {
            TenantId = scope.Value.TenantId,
            ActorId = scope.Value.ActorId,
            Fingerprint = fingerprint,
            IdempotencyKey = request.IdempotencyKey,
            Snapshot = snapshot,
            Event = new WorkItemEvent(request.Id, 0, 0, request.InitialStep, "Created", snapshot.BasisJson, now),
            ResultJson = resultJson,
            Outbox = [CreateOutbox(scope.Value.TenantId, snapshot, "Created", snapshot.BasisJson)],
        };
        return FromStore(await CommitAsync(WorkItemCommitKind.Create, commit, cancellationToken).ConfigureAwait(false));
    }

    /// <inheritdoc />
    public async Task<WorkItemSnapshot?> GetAsync(string workItemId, CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(workItemId);
        var scope = await ScopeAsync(cancellationToken).ConfigureAwait(false);
        return scope is null ? null : await _store.GetAsync(scope.Value.TenantId, workItemId, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<IReadOnlyList<WorkItemSnapshot>> ListOpenAsync(CancellationToken cancellationToken = default)
    {
        var scope = await ScopeAsync(cancellationToken).ConfigureAwait(false);
        return scope is null
            ? Array.Empty<WorkItemSnapshot>()
            : await _store.ListOpenAsync(scope.Value.TenantId, cancellationToken).ConfigureAwait(false);
    }

    /// <inheritdoc />
    public async Task<WorkItemMutationResult> TransitionAsync(TransitionWorkItemRequest request, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(request);
        ValidateTransition(request);
        var scope = await ScopeAsync(cancellationToken).ConfigureAwait(false);
        if (scope is null) return Denied();

        string fingerprint;
        try { fingerprint = WorkItemCanonical.TransitionFingerprint(scope.Value.TenantId, request); }
        catch (JsonException) { return Invalid(); }

        var replay = await ReplayAsync(scope.Value.TenantId, request.IdempotencyKey, fingerprint, cancellationToken).ConfigureAwait(false);
        if (replay is not null) return replay;

        var current = await _store.GetAsync(scope.Value.TenantId, request.Id, cancellationToken).ConfigureAwait(false);
        if (current is null) return new(WorkItemMutationDisposition.NotFound, null, null);
        if (current.Version != request.ExpectedVersion)
            return new(WorkItemMutationDisposition.VersionConflict, current, null);
        if (current.Status is WorkItemStatus.Completed or WorkItemStatus.Failed)
            return Invalid();

        var outcome = current.AllowedOutcomes.SingleOrDefault(candidate =>
            StringComparer.Ordinal.Equals(candidate.Id, request.OutcomeId)
            && StringComparer.Ordinal.Equals(candidate.FromStep, current.CurrentStep));
        if (outcome is null) return Invalid();

        var now = _time.GetUtcNow();
        var next = current with
        {
            CurrentStep = outcome.NextStep,
            Iteration = current.Iteration + (outcome.IsLoopBack ? 1 : 0),
            Version = current.Version + 1,
            Status = outcome.NextStatus,
            UpdatedAt = now,
        };
        var resultJson = WorkItemCanonical.NormalizeJson(request.ResultJson);
        var commit = new WorkItemCommit
        {
            TenantId = scope.Value.TenantId,
            ActorId = scope.Value.ActorId,
            Fingerprint = fingerprint,
            IdempotencyKey = request.IdempotencyKey,
            Snapshot = next,
            Event = new WorkItemEvent(request.Id, current.Version, next.Iteration, current.CurrentStep, outcome.Id, resultJson, now),
            ResultJson = resultJson,
            Outbox = [CreateOutbox(scope.Value.TenantId, next, outcome.Id, resultJson)],
            ExpectedVersion = request.ExpectedVersion,
            ExpectedStep = current.CurrentStep,
        };
        return FromStore(await CommitAsync(WorkItemCommitKind.Transition, commit, cancellationToken).ConfigureAwait(false));
    }

    /// <summary>Returns the stable deterministic key for a current snapshot.</summary>
    public static string DeriveStepKey(string tenantId, WorkItemSnapshot snapshot)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(tenantId);
        ArgumentNullException.ThrowIfNull(snapshot);
        return WorkItemCanonical.StepKey(tenantId, snapshot);
    }

    private async Task<WorkItemMutationResult?> ReplayAsync(string tenantId, string key, string fingerprint, CancellationToken cancellationToken)
    {
        var receipt = await _store.GetReceiptAsync(tenantId, key, cancellationToken).ConfigureAwait(false);
        if (receipt is null) return null;
        return StringComparer.Ordinal.Equals(receipt.Fingerprint, fingerprint)
            ? new(WorkItemMutationDisposition.Replayed, receipt.Snapshot, receipt.ResultJson)
            : new(WorkItemMutationDisposition.IdempotencyConflict, null, null);
    }

    private async ValueTask<WorkItemStoreResult> CommitAsync(
        WorkItemCommitKind kind,
        WorkItemCommit commit,
        CancellationToken cancellationToken)
    {
        var command = new KernelCommand<WorkItemAtomicCommit>(
            new(commit.Snapshot.Id, commit.IdempotencyKey, commit.Fingerprint),
            new(kind, commit),
            new(
                $"{commit.TenantId}:{commit.Snapshot.Id}:{commit.Snapshot.Version}:audit",
                commit.ActorId,
                commit.Event.OccurredAt,
                Encoding.UTF8.GetBytes(commit.Event.DataJson)));
        var result = await KernelTransactionBoundary.ExecuteAsync(
            [command],
            new WorkItemKernelTransactionPort(_store),
            cancellationToken).ConfigureAwait(false);
        return result.Value
            ?? throw new InvalidOperationException(result.Refusal?.Code ?? "The kernel transaction did not return a result.");
    }

    private async ValueTask<(string TenantId, string ActorId)?> ScopeAsync(CancellationToken cancellationToken)
    {
        var tenant = _tenantContext.Tenant;
        if (tenant is null || tenant.Status != TenantStatus.Active || tenant.Id.IsSystemSentinel) return null;
        try
        {
            var partyId = await _partyContext.GetCurrentPartyIdAsync(cancellationToken).ConfigureAwait(false);
            return partyId == Guid.Empty ? null : (tenant.Id.Value, partyId.ToString("D"));
        }
        catch (PrincipalPartyResolutionException)
        {
            return null;
        }
    }

    private static WorkItemOutboxMessage CreateOutbox(string tenantId, WorkItemSnapshot snapshot, string action, string dataJson) =>
        new(
            $"{tenantId}:{snapshot.Id}:{snapshot.Version}",
            snapshot.Version == 1 ? "work-item.created" : "work-item.transitioned",
            JsonSerializer.Serialize(new
            {
                tenantId,
                workItemId = snapshot.Id,
                snapshot.SubjectRef,
                snapshot.Version,
                snapshot.Iteration,
                snapshot.CurrentStep,
                status = snapshot.Status.ToString(),
                action,
                data = ParseJson(dataJson),
            }));

    private static JsonElement ParseJson(string value)
    {
        using var document = JsonDocument.Parse(value);
        return document.RootElement.Clone();
    }

    private static WorkItemMutationResult FromStore(WorkItemStoreResult result) =>
        new(result.Disposition, result.Receipt?.Snapshot, result.Receipt?.ResultJson);
    private static WorkItemMutationResult Denied() => new(WorkItemMutationDisposition.Denied, null, null);
    private static WorkItemMutationResult Invalid() => new(WorkItemMutationDisposition.InvalidTransition, null, null);

    private static void ValidateCreate(CreateWorkItemRequest request)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(request.Id);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.SubjectRef);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.DefinitionKey);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.DefinitionVersion);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.InitialStep);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.IdempotencyKey);
        if (request.AllowedOutcomes.Count == 0) throw new ArgumentException("At least one typed outcome is required.", nameof(request));
        var outcomeKeys = new HashSet<string>(StringComparer.Ordinal);
        foreach (var outcome in request.AllowedOutcomes)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(outcome.Id);
            ArgumentException.ThrowIfNullOrWhiteSpace(outcome.FromStep);
            ArgumentException.ThrowIfNullOrWhiteSpace(outcome.NextStep);
            if (!outcomeKeys.Add($"{outcome.FromStep}\u001f{outcome.Id}"))
                throw new ArgumentException("Outcome IDs must be unique within a source step.", nameof(request));
        }
        if (request.InitialStatus is WorkItemStatus.Completed or WorkItemStatus.Failed)
            throw new ArgumentException("A new work item must be running or parked.", nameof(request));
    }

    private static void ValidateTransition(TransitionWorkItemRequest request)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(request.Id);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(request.ExpectedVersion);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.IdempotencyKey);
        ArgumentException.ThrowIfNullOrWhiteSpace(request.OutcomeId);
    }
}

using System.Text;
using Harborline.Kernel.Core;

namespace Harborline.Kernel.WorkItems;

internal enum WorkItemCommitKind { Create, Transition }

internal sealed record WorkItemAtomicCommit(WorkItemCommitKind Kind, WorkItemCommit Commit);

internal sealed class WorkItemKernelTransactionPort(IWorkItemStore store)
    : IKernelTransactionPort<WorkItemAtomicCommit, WorkItemStoreResult>
{
    private readonly IWorkItemStore _store = store ?? throw new ArgumentNullException(nameof(store));

    public ValueTask<IKernelTransaction<WorkItemAtomicCommit, WorkItemStoreResult>> BeginAsync(
        KernelOperationIdentity operation,
        CancellationToken cancellationToken = default) =>
        ValueTask.FromResult<IKernelTransaction<WorkItemAtomicCommit, WorkItemStoreResult>>(
            new Transaction(_store, operation));

    private sealed class Transaction(IWorkItemStore store, KernelOperationIdentity operation)
        : IKernelTransaction<WorkItemAtomicCommit, WorkItemStoreResult>
    {
        private WorkItemAtomicCommit? _record;
        private KernelAuditEvidence? _audit;

        public ValueTask StageRecordAsync(WorkItemAtomicCommit record, CancellationToken cancellationToken = default)
        {
            ArgumentNullException.ThrowIfNull(record);
            if (!StringComparer.Ordinal.Equals(operation.CommandId, record.Commit.Snapshot.Id)
                || !StringComparer.Ordinal.Equals(operation.IdempotencyKey, record.Commit.IdempotencyKey)
                || !StringComparer.Ordinal.Equals(operation.Fingerprint, record.Commit.Fingerprint))
                throw new InvalidOperationException("The work-item commit does not match its kernel operation identity.");
            _record = record;
            return ValueTask.CompletedTask;
        }

        public ValueTask StageAuditAsync(KernelAuditEvidence audit, CancellationToken cancellationToken = default)
        {
            ArgumentNullException.ThrowIfNull(audit);
            var commit = _record?.Commit ?? throw new InvalidOperationException("The record must be staged before its audit.");
            if (!StringComparer.Ordinal.Equals(audit.ActorId, commit.ActorId)
                || audit.RecordedAt != commit.Event.OccurredAt
                || !audit.Payload.Span.SequenceEqual(Encoding.UTF8.GetBytes(commit.Event.DataJson)))
                throw new InvalidOperationException("The work-item audit does not match the staged commit.");
            _audit = audit;
            return ValueTask.CompletedTask;
        }

        public async ValueTask<WorkItemStoreResult> CommitAsync(CancellationToken cancellationToken = default)
        {
            var record = _record ?? throw new InvalidOperationException("A complete record and audit set is required.");
            if (_audit is null) throw new InvalidOperationException("A complete record and audit set is required.");
            return record.Kind == WorkItemCommitKind.Create
                ? await store.CommitCreateAsync(record.Commit, cancellationToken).ConfigureAwait(false)
                : await store.CommitTransitionAsync(record.Commit, cancellationToken).ConfigureAwait(false);
        }

        public ValueTask RollbackAsync(CancellationToken cancellationToken = default)
        {
            _record = null;
            _audit = null;
            return ValueTask.CompletedTask;
        }

        public ValueTask DisposeAsync()
        {
            _record = null;
            _audit = null;
            return ValueTask.CompletedTask;
        }
    }
}

namespace Harborline.Kernel.WorkItems;

/// <summary>Storage transaction generated by the kernel after context and request admission.</summary>
public sealed record WorkItemCommit
{
    /// <summary>Current tenant wire identifier.</summary>
    public required string TenantId { get; init; }
    /// <summary>Canonical request fingerprint.</summary>
    public required string Fingerprint { get; init; }
    /// <summary>Retry key scoped to tenant and operation.</summary>
    public required string IdempotencyKey { get; init; }
    /// <summary>Actor derived from the current authenticated host scope.</summary>
    public required string ActorId { get; init; }
    /// <summary>New immutable snapshot.</summary>
    public required WorkItemSnapshot Snapshot { get; init; }
    /// <summary>Append-only event.</summary>
    public required WorkItemEvent Event { get; init; }
    /// <summary>Replay result.</summary>
    public required string ResultJson { get; init; }
    /// <summary>Optional immutable outbox messages.</summary>
    public IReadOnlyList<WorkItemOutboxMessage> Outbox { get; init; } = Array.Empty<WorkItemOutboxMessage>();
    /// <summary>Expected prior version, or null for create.</summary>
    public long? ExpectedVersion { get; init; }
    /// <summary>Expected prior step, or null for create.</summary>
    public string? ExpectedStep { get; init; }
}

/// <summary>Append-only work-item history event.</summary>
public sealed record WorkItemEvent(
    string WorkItemId,
    long Sequence,
    int Iteration,
    string Step,
    string Action,
    string DataJson,
    DateTimeOffset OccurredAt);

/// <summary>Actor audit committed in the same transaction as work-item state.</summary>
public sealed record WorkItemAudit(
    string WorkItemId,
    long WorkItemVersion,
    string ActorId,
    string Action,
    DateTimeOffset OccurredAt);

/// <summary>Fingerprint-bound retry receipt.</summary>
public sealed record WorkItemIdempotencyReceipt(
    string Key,
    string Fingerprint,
    WorkItemSnapshot Snapshot,
    string ResultJson);

/// <summary>Provider-neutral atomic persistence port.</summary>
public interface IWorkItemStore
{
    /// <summary>Loads a tenant-scoped snapshot.</summary>
    Task<WorkItemSnapshot?> GetAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default);
    /// <summary>Lists open tenant-scoped snapshots.</summary>
    Task<IReadOnlyList<WorkItemSnapshot>> ListOpenAsync(string tenantId, CancellationToken cancellationToken = default);
    /// <summary>Loads a retry receipt scoped to tenant and key.</summary>
    Task<WorkItemIdempotencyReceipt?> GetReceiptAsync(string tenantId, string idempotencyKey, CancellationToken cancellationToken = default);
    /// <summary>Commits create state, event, receipt, audit, and outbox atomically.</summary>
    Task<WorkItemStoreResult> CommitCreateAsync(WorkItemCommit commit, CancellationToken cancellationToken = default);
    /// <summary>Commits a version-guarded transition atomically.</summary>
    Task<WorkItemStoreResult> CommitTransitionAsync(WorkItemCommit commit, CancellationToken cancellationToken = default);
}

/// <summary>Atomic store result.</summary>
public sealed record WorkItemStoreResult(WorkItemMutationDisposition Disposition, WorkItemIdempotencyReceipt? Receipt);

/// <summary>Optional inspection port for event, audit, and outbox delivery adapters.</summary>
public interface IWorkItemJournalReader
{
    /// <summary>Returns current-tenant history for one item.</summary>
    Task<IReadOnlyList<WorkItemEvent>> ReadEventsAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default);
    /// <summary>Returns current-tenant audit records for one item.</summary>
    Task<IReadOnlyList<WorkItemAudit>> ReadAuditAsync(string tenantId, string workItemId, CancellationToken cancellationToken = default);
    /// <summary>Returns committed current-tenant outbox messages.</summary>
    Task<IReadOnlyList<WorkItemOutboxMessage>> ReadOutboxAsync(string tenantId, CancellationToken cancellationToken = default);
}

